def find_side_lengths(n):
    if n < 1:
        return "impossible"

    m = int(n**0.5)

    while m >= 0:
        k = int((m**2 - n)**0.5)
        if m**2 - k**2 == n:
            return m, k
        m -= 1

    return "impossible"

